import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.B8TleWq7.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md"}'),n={name:"reference/troubleshooting.md"};function s(d,e,i,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Find the symptom, then the cause and fix.</p><h2 id="nothing-boots" tabindex="-1">Nothing boots <a class="header-anchor" href="#nothing-boots" aria-label="Permalink to &quot;Nothing boots&quot;">​</a></h2><h3 id="no-loader-server-booted-or-loader-client-booted-line" tabindex="-1">No <code>[Loader] Server booted</code> or <code>[Loader] Client booted</code> line <a class="header-anchor" href="#no-loader-server-booted-or-loader-client-booted-line" aria-label="Permalink to &quot;No `[Loader] Server booted` or `[Loader] Client booted` line&quot;">​</a></h3><ul><li>Script Sync is not connected to one or more of the six root Folders, or the Folder names do not match. See <a href="/Keel-Docs/getting-started/connect-studio">Connect Roblox Studio</a>.</li><li>Check the Output for an error above the missing line: a boot error stops everything after it.</li></ul><h3 id="the-boot-stops-with-an-error-naming-dependencies" tabindex="-1">The boot stops with an error naming dependencies <a class="header-anchor" href="#the-boot-stops-with-an-error-naming-dependencies" aria-label="Permalink to &quot;The boot stops with an error naming dependencies&quot;">​</a></h3><p>The Loader stops the boot for: a dependency cycle (<code>Loader: dependency cycle: A -&gt; B -&gt; C -&gt; A</code>), a <code>Dependencies</code> name no module has (usually a typo), a module with no <code>Name</code> or two with the same <code>Name</code>, an <code>Hz</code> that is not a positive number, or <code>Dependencies</code> that is not a list. Fix the module named in the message.</p><h3 id="prerender-runs-only-on-the-client" tabindex="-1"><code>PreRender runs only on the client</code> <a class="header-anchor" href="#prerender-runs-only-on-the-client" aria-label="Permalink to &quot;`PreRender runs only on the client`&quot;">​</a></h3><p>A server module (a Service or System) has a <code>PreRender</code> method. The server never renders, so there is nothing to call it before. Move camera or visual work to a Controller; for per-frame server work before physics use <code>PreSimulation</code>, or <code>Update</code> with <code>Hz</code> for game logic.</p><h3 id="init-waited" tabindex="-1"><code>Init waited</code> <a class="header-anchor" href="#init-waited" aria-label="Permalink to &quot;`Init waited`&quot;">​</a></h3><p>A module&#39;s <code>Init</code> waited. <code>Init</code> must not wait or call other modules. Move the work to <code>Start</code> or <code>task.spawn</code>. The rest of that <code>Init</code> still runs later.</p><h3 id="waited-so-it-was-stopped-scheduler" tabindex="-1"><code>… waited, so it was stopped</code> (Scheduler) <a class="header-anchor" href="#waited-so-it-was-stopped-scheduler" aria-label="Permalink to &quot;`… waited, so it was stopped` (Scheduler)&quot;">​</a></h3><p>An <code>Update</code>, <code>PreSimulation</code> or <code>PreRender</code> waited (the message names which). That hook is removed from the Scheduler, because every call would otherwise leave another paused copy running. Put waiting work in <code>task.spawn</code>.</p><h3 id="one-module-failed-but-the-game-still-runs" tabindex="-1">One module failed but the game still runs <a class="header-anchor" href="#one-module-failed-but-the-game-still-runs" aria-label="Permalink to &quot;One module failed but the game still runs&quot;">​</a></h3><p>By design. A module that errors while loading, in <code>Init</code> or in <code>Start</code> is skipped from then on, and modules depending on it get a warning. Fix the first error in the Output.</p><h2 id="script-sync-and-the-editor" tabindex="-1">Script Sync and the editor <a class="header-anchor" href="#script-sync-and-the-editor" aria-label="Permalink to &quot;Script Sync and the editor&quot;">​</a></h2><h3 id="the-keel-setup-button-isn-t-in-studio" tabindex="-1">The Keel Setup button isn&#39;t in Studio <a class="header-anchor" href="#the-keel-setup-button-isn-t-in-studio" aria-label="Permalink to &quot;The Keel Setup button isn&#39;t in Studio&quot;">​</a></h3><p>The plugin must be in Studio&#39;s Plugins folder (Plugins tab, Plugins Folder) as <code>KeelSetup.lua</code>, and Studio must be restarted after copying it. Copy it from <code>tools/KeelSetup.lua</code> in your game.</p><h3 id="the-folders-exist-but-nothing-syncs" tabindex="-1">The Folders exist but nothing syncs <a class="header-anchor" href="#the-folders-exist-but-nothing-syncs" aria-label="Permalink to &quot;The Folders exist but nothing syncs&quot;">​</a></h3><p>Creating the Folders is not enough: each one must be connected to its disk folder with <strong>Script Sync, Sync with Directory, Keep Disk</strong>. The plugin&#39;s checklist shows the disk folder for each. See <a href="/Keel-Docs/getting-started/connect-studio">Connect Roblox Studio</a>.</p><h3 id="i-reopened-my-place-and-the-sync-is-gone" tabindex="-1">I reopened my place and the sync is gone <a class="header-anchor" href="#i-reopened-my-place-and-the-sync-is-gone" aria-label="Permalink to &quot;I reopened my place and the sync is gone&quot;">​</a></h3><p>Script Sync connections are not stored in the place file, so they do not travel with a copied or re-saved place. Reconnect the six Folders. (A template place with the connections pre-made was tried and does not work.)</p><h3 id="a-new-folder-isn-t-in-studio" tabindex="-1">A new folder isn&#39;t in Studio <a class="header-anchor" href="#a-new-folder-isn-t-in-studio" aria-label="Permalink to &quot;A new folder isn&#39;t in Studio&quot;">​</a></h3><p>A folder with only a <code>.gitkeep</code> does not sync. Add a <code>.luau</code> file to it.</p><h3 id="errors-open-a-copy-of-my-script-that-i-can-t-keep" tabindex="-1">Errors open a copy of my script that I can&#39;t keep <a class="header-anchor" href="#errors-open-a-copy-of-my-script-that-i-can-t-keep" aria-label="Permalink to &quot;Errors open a copy of my script that I can&#39;t keep&quot;">​</a></h3><p>You put client code in <code>StarterPlayerScripts</code>, which is cloned into each player. Client code belongs in <code>ReplicatedFirst/Client</code>.</p><h3 id="red-underlines-on-correct-code-in-vs-code" tabindex="-1">Red underlines on correct code in VS Code <a class="header-anchor" href="#red-underlines-on-correct-code-in-vs-code" aria-label="Permalink to &quot;Red underlines on correct code in VS Code&quot;">​</a></h3><p>The Luau extension needs the sourcemap. Run <code>node tools/sourcemap.js</code> once, or reload VS Code. Instances that exist only in Studio (Workspace parts, Studio-built UI) are unknown to it.</p><h3 id="stylua-rejects-a-file-after-a-windows-clone" tabindex="-1">StyLua rejects a file after a Windows clone <a class="header-anchor" href="#stylua-rejects-a-file-after-a-windows-clone" aria-label="Permalink to &quot;StyLua rejects a file after a Windows clone&quot;">​</a></h3><p>Keel 0.1.0 wrote CRLF line endings on Windows. 0.1.1 writes LF and adds a <code>.gitattributes</code> that keeps LF on checkout. Update to 0.1.1 or later.</p><h2 id="defs" tabindex="-1">Defs <a class="header-anchor" href="#defs" aria-label="Permalink to &quot;Defs&quot;">​</a></h2><h3 id="defs-n-problem-s-found-stops-studio-from-booting" tabindex="-1"><code>Defs: N problem(s) found</code> stops Studio from booting <a class="header-anchor" href="#defs-n-problem-s-found-stops-studio-from-booting" aria-label="Permalink to &quot;`Defs: N problem(s) found` stops Studio from booting&quot;">​</a></h3><p>Every problem is listed with its path, such as <code>Items.sword_iron.Weapon: no Weapons entry &quot;blde&quot;</code>. In Studio any problem stops boot. On a live server the broken entry is disabled and logged instead, and so is any entry that referred to it.</p><h3 id="my-kind-isn-t-registered" tabindex="-1">My kind isn&#39;t registered <a class="header-anchor" href="#my-kind-isn-t-registered" aria-label="Permalink to &quot;My kind isn&#39;t registered&quot;">​</a></h3><p>A kind in a module nothing requires is not registered. Keep Defs modules in <code>Shared/Defs</code> or <code>Server/Defs</code>, which <code>Defs.Boot</code> loads.</p><h2 id="networking" tabindex="-1">Networking <a class="header-anchor" href="#networking" aria-label="Permalink to &quot;Networking&quot;">​</a></h2><h3 id="net-bob-sent-shop-buy-arg-2-dropped" tabindex="-1"><code>[Net] Bob sent Shop.Buy: arg 2: … (dropped)</code> <a class="header-anchor" href="#net-bob-sent-shop-buy-arg-2-dropped" aria-label="Permalink to &quot;`[Net] Bob sent Shop.Buy: arg 2: … (dropped)`&quot;">​</a></h3><p>Net rejected a client message before any handler ran: it failed a rate or argument check. It logs at most once per 10 seconds per player per message. If it is your own client, fix what you send.</p><h3 id="an-error-saying-a-send-must-come-from-start-or-later" tabindex="-1">An error saying a send must come from <code>Start</code> or later <a class="header-anchor" href="#an-error-saying-a-send-must-come-from-start-or-later" aria-label="Permalink to &quot;An error saying a send must come from `Start` or later&quot;">​</a></h3><p>A client sent before <code>Net.WaitForServer()</code> finished. Send from a Controller&#39;s <code>Start</code>, not from top-level code or <code>Init</code>.</p><h3 id="the-257th-message-errors" tabindex="-1">The 257th message errors <a class="header-anchor" href="#the-257th-message-errors" aria-label="Permalink to &quot;The 257th message errors&quot;">​</a></h3><p>A game can have 256 messages, Net&#39;s internal <code>Keel.Ready</code> included.</p><h3 id="a-request-returns-false-timeout-no-handler-error" tabindex="-1">A request returns <code>false, &quot;timeout&quot;</code> / <code>&quot;no handler&quot;</code> / <code>&quot;error&quot;</code> <a class="header-anchor" href="#a-request-returns-false-timeout-no-handler-error" aria-label="Permalink to &quot;A request returns `false, &quot;timeout&quot;` / `&quot;no handler&quot;` / `&quot;error&quot;`&quot;">​</a></h3><p>No answer within 10 seconds, no <code>OnInvoke</code> handler registered, or the handler errored or returned something other than <code>(boolean, string?)</code>. A rejected one answers <code>&quot;invalid&quot;</code> or <code>&quot;rate limited&quot;</code>.</p><h3 id="messages-sent-to-a-joining-player-seem-lost" tabindex="-1">Messages sent to a joining player seem lost <a class="header-anchor" href="#messages-sent-to-a-joining-player-seem-lost" aria-label="Permalink to &quot;Messages sent to a joining player seem lost&quot;">​</a></h3><p>They are queued (up to 256) and delivered in order once the client calls <code>Net.ClientReady()</code>. If the client never gets that far, they never arrive. Check that the client boot completed.</p><h2 id="player-data" tabindex="-1">Player data <a class="header-anchor" href="#player-data" aria-label="Permalink to &quot;Player data&quot;">​</a></h2><h3 id="a-player-is-kicked-on-join" tabindex="-1">A player is kicked on join <a class="header-anchor" href="#a-player-is-kicked-on-join" aria-label="Permalink to &quot;A player is kicked on join&quot;">​</a></h3><p>Data kicks instead of letting anyone play on empty data: no session could be started, a migration failed, the save is from a newer version than this server knows, or another server took the session. The reason is logged.</p><h3 id="nothing-saves-in-studio" tabindex="-1">Nothing saves in Studio <a class="header-anchor" href="#nothing-saves-in-studio" aria-label="Permalink to &quot;Nothing saves in Studio&quot;">​</a></h3><p>Without API access, Studio uses ProfileStore&#39;s mock store. Turn API access on to test saving. <code>FreshData = true</code> also uses a throwaway store on purpose.</p><h3 id="a-value-i-changed-doesn-t-appear-on-the-client" tabindex="-1">A value I changed doesn&#39;t appear on the client <a class="header-anchor" href="#a-value-i-changed-doesn-t-appear-on-the-client" aria-label="Permalink to &quot;A value I changed doesn&#39;t appear on the client&quot;">​</a></h3><p>Use <code>Replica.Set</code>. A direct write to <code>Data.Get(player)</code> is saved but not sent. See <a href="/Keel-Docs/guides/state-and-replica">State and Replica</a>.</p><h3 id="replica-set-errors" tabindex="-1"><code>Replica.Set</code> errors <a class="header-anchor" href="#replica-set-errors" aria-label="Permalink to &quot;`Replica.Set` errors&quot;">​</a></h3><p>The path must be inside a replicated component, the value must be plain data (finite numbers, booleans, strings up to 255 bytes, tables of those, at most 8 deep), and the player&#39;s data must have loaded.</p><h2 id="purchases" tabindex="-1">Purchases <a class="header-anchor" href="#purchases" aria-label="Permalink to &quot;Purchases&quot;">​</a></h2><h3 id="the-purchase-prompt-fails-or-a-subscription-lookup-logs-http-400" tabindex="-1">The purchase prompt fails, or a subscription lookup logs <code>HTTP 400</code> <a class="header-anchor" href="#the-purchase-prompt-fails-or-a-subscription-lookup-logs-http-400" aria-label="Permalink to &quot;The purchase prompt fails, or a subscription lookup logs `HTTP 400`&quot;">​</a></h3><p>The entry has a made-up Roblox id. Use <code>testbuy</code> and <code>testpass</code> in Studio until the real product exists in the Creator Hub.</p><h3 id="testbuy-errors" tabindex="-1"><code>testbuy</code> errors <a class="header-anchor" href="#testbuy-errors" aria-label="Permalink to &quot;`testbuy` errors&quot;">​</a></h3><p>TestMode works in Studio only.</p><h3 id="a-product-is-never-granted" tabindex="-1">A product is never granted <a class="header-anchor" href="#a-product-is-never-granted" aria-label="Permalink to &quot;A product is never granted&quot;">​</a></h3><p>The receipt answers <code>NotProcessedYet</code> when there is no Products entry for the <code>ProductId</code>, no <code>OnProduct</code> handler, the player&#39;s data is not loaded, or the handler errored, waited or returned <code>false</code>. Check the Output for the logged error.</p><h2 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h2><h3 id="the-console-won-t-open" tabindex="-1">The console won&#39;t open <a class="header-anchor" href="#the-console-won-t-open" aria-label="Permalink to &quot;The console won&#39;t open&quot;">​</a></h3><p>Press <strong>F2</strong>. Outside Studio only the UserIds in <code>Server/Defs/Admins</code> may use it.</p><h3 id="requiring-cmdr-from-the-command-bar-fails" tabindex="-1">Requiring Cmdr from the command bar fails <a class="header-anchor" href="#requiring-cmdr-from-the-command-bar-fails" aria-label="Permalink to &quot;Requiring Cmdr from the command bar fails&quot;">​</a></h3><p>Do not. Cmdr moves its client folder on first require, so only <code>Console</code> may require it.</p><h2 id="tests-and-the-command-bar" tabindex="-1">Tests and the command bar <a class="header-anchor" href="#tests-and-the-command-bar" aria-label="Permalink to &quot;Tests and the command bar&quot;">​</a></h2><h3 id="my-code-change-isn-t-seen-by-the-tests" tabindex="-1">My code change isn&#39;t seen by the tests <a class="header-anchor" href="#my-code-change-isn-t-seen-by-the-tests" aria-label="Permalink to &quot;My code change isn&#39;t seen by the tests&quot;">​</a></h3><p><code>require</code> caches modules for the whole playtest. Stop and start the playtest again.</p><h3 id="a-module-i-require-from-the-command-bar-behaves-oddly" tabindex="-1">A module I <code>require</code> from the command bar behaves oddly <a class="header-anchor" href="#a-module-i-require-from-the-command-bar-behaves-oddly" aria-label="Permalink to &quot;A module I `require` from the command bar behaves oddly&quot;">​</a></h3><p>The command bar and the Studio MCP get their own copy of every module. Call <code>Net.WaitForServer()</code> first in that copy.</p><h2 id="updating-keel" tabindex="-1">Updating Keel <a class="header-anchor" href="#updating-keel" aria-label="Permalink to &quot;Updating Keel&quot;">​</a></h2><h3 id="update-says-keel-files-were-edited" tabindex="-1"><code>update</code> says Keel files were edited <a class="header-anchor" href="#update-says-keel-files-were-edited" aria-label="Permalink to &quot;`update` says Keel files were edited&quot;">​</a></h3><p>An owned file no longer matches its recorded hash. Move the change into the Keel repo, or run again with <code>--force</code> to discard it. See <a href="/Keel-Docs/getting-started/update-keel">Update Keel</a>.</p><h3 id="update-says-there-is-no-keel-json" tabindex="-1"><code>update</code> says there is no <code>keel.json</code> <a class="header-anchor" href="#update-says-there-is-no-keel-json" aria-label="Permalink to &quot;`update` says there is no `keel.json`&quot;">​</a></h3><p>The game was not created by <code>keel.js new</code>. Run <code>node tools/keel.js update &lt;tag&gt; --force</code> once to adopt it.</p>',77)])])}const m=o(n,[["render",s]]);export{p as __pageData,m as default};
